                            {
                              fileCount: fileCount ?? 0,
                              totalSizeBytes: totalSizeBytes ?? 0,
                            },
                          )}
                        </div>
                      );
                    }}
                  </Form.Item>
                </div>
              </Form.Item>

              <Form.Item hidden name="storageType">
                <Input />
              </Form.Item>
              <Form.Item hidden name="storageBucket">
